@startuml
class Employee {}
class HeadCoach extends Employee {}
class Director extends Employee {}
class Scout extends Employee {}
class HeadScout extends Scout {}

class PlayerProfile {
  +targetPosition : string
}

class PlayerAttribute {
  +name : string
  +value : string
}

class Player {
  +name : string
}

class LongList {
  +dateAdded : date
}

class ScoutingAssignment {
  +date : date
}

class ScoutingReport {
  +pros : string
  +cons : string
  +recommendation : string
}

class ShortList {}

class OfficialOffer {}

HeadCoach "1" -- "*" PlayerProfile : identifies
PlayerProfile "1" *-- "*" PlayerAttribute : includes

Scout "1" -- "*" LongList : notes players on
LongList "1" -- "*" Scout : evaluated by
HeadScout "1" -- "*" ScoutingAssignment : sets up

ScoutingAssignment "0..*" -- "1" Player : investigates
ScoutingAssignment "1" -- "1" Scout : carried out by
ScoutingAssignment "1" -- "1" ScoutingReport : results in

Player "0..*" -- "0..1" ShortList : moved to
HeadCoach "1" -- "*" ShortList : decides upon
HeadScout "1" -- "*" ShortList : decides upon

HeadScout "1" -- "0..1" OfficialOffer : recommends
Director "1" -- "*" OfficialOffer : makes
OfficialOffer "1" -- "1" Player : for
@enduml

